def decode_block(value):              #Decode base 26 number back into 3 letters
    c2 = 'A' + (value % 26)
    value //= 26
    c1 = 'A' + (value % 26)
    value //= 26
    c0 = 'A' + (value % 26)
    return c0+c1+c2

def build_lookup_table(n, e):
    lookup = {}

    total = 26*26*26

    print("Buidling lookup table with 17576 possible 3-letter blocks.")

    for m in range(total):
        c = pow(m, e, n)
        lookup[c] = m

    print("Complete")
    return lookup

